      "keystrokes": "vncsnapshot -vnc localhost:5901 /tmp/vnc-screenshot.jpg 2>&1 || vncsnapshot localhost:5901 /tmp/vnc-screenshot.jpg 2>&1 || true\n",
      "duration": 1.0
