      "keystrokes": "python3 -c 'import socket, time; s=socket.socket(socket.AF_UNIX, socket.SOCK_STREAM); s.connect(\"/tmp/qemu-monitor.sock\"); s.send(b\"sendkey ret\\n\"); time.sleep(0.5); print(s.recv(4096).decode()); s.close()'\n",
      "duration": 1.0
